import json, collections, sys
exec(open('/work/load.py').read())
EVAL='2026-09-24T12:00'
ANTICOAG=['warfarin','apixaban','rivaroxaban','dabigatran','edoxaban','enoxaparin','heparin','fondaparinux','argatroban','bivalirudin']
QTDRUG=['citalopram','escitalopram','haloperidol','methadone','amiodarone','sotalol','dofetilide']
ecgs=json.load(open('ecgs.json'))['ecgs']
ecgby=collections.defaultdict(list)
for e in ecgs: ecgby[e['patient']].append(e)
labs={}
for code,name in [('51237','INR'),('50971','K'),('50822','K_wb'),('50960','Mg')]:
    for l in open(f'obs_{code}.ndjson'):
        o=json.loads(l); labs.setdefault(o['subject']['reference'].split('/')[-1],[]).append(
            (o.get('effectiveDateTime',''),name,o.get('valueQuantity',{}).get('value'),o.get('valueQuantity',{}).get('unit'),o['id']))

def dossier(p, full=False):
    L=[]
    pt=pats[p]
    L.append(f"=== PATIENT {p} mrn={pt['identifier'][0]['value']} dob={pt['birthDate']} {pt['gender']} deceased={pt.get('deceasedDateTime')}")
    cs=[c for c in conds if c['pat']==p]
    seen=set()
    for c in cs:
        d=c['code']['coding'][0].get('display'); 
        if d in seen and not full: continue
        seen.add(d)
        L.append(f"  COND {c.get('recordedDate') or c.get('onsetDateTime')} {d} [{c['id']}]")
    for r in sorted([r for r in mreq if r['pat']==p], key=lambda r:r['authoredOn']):
        n=(r['med'] or '').lower()
        if not (any(k in n for k in ANTICOAG+QTDRUG) or full): continue
        vp=r.get('dispenseRequest',{}).get('validityPeriod',{})
        cur='CURRENT' if vp.get('start','')<=EVAL<=vp.get('end','~') else ''
        L.append(f"  MEDREQ {r['authoredOn'][:16]} {r['med']} | {r.get('dosageInstruction',[{}])[0].get('text')} | {vp.get('start','')[:10]}..{vp.get('end','')[:10]} {r['status']} {cur} [{r['id']}]")
    for e in ecgby.get(p,[]): L.append(f"  ECG {e['time']} {e['ecg']}")
    for x in sorted(labs.get(p,[]))[-12:]: L.append(f"  LAB {x[0][:16]} {x[1]}={x[2]} {x[3]} [{x[4]}]")
    for n in sorted([n for n in notes if n['pat']==p], key=lambda n:n['date']):
        if n['date']<'2025-01-01' and not full: continue
        L.append(f"  --- NOTE {n['date'][:16]} {n['type']} role={n['role']} {n['author']} [{n['id']}] enc={n['enc']}")
        L.append('    '+n['text'].replace('\n','\n    '))
    return '\n'.join(L)

if __name__=='__main__':
    for p in sys.argv[1:]:
        print(dossier(p, full=('--full' in sys.argv)))
